    std::vector<std::pair<int64_t, int64_t>> merged;
    merged.reserve(ranges.size());

    for (const auto& [l, r] : ranges) {
        if (merged.empty()) {
            merged.emplace_back(l, r);
        } else {
            auto& back = merged.back();
            // Merge if overlapping or adjacent.
            // Adjacent means l == back.second + 1, but we must avoid overflow.
            // Safe check: l <= back.second + 1 is equivalent to l - 1 <= back.second
            // when l > 0. However, a more robust way:
            // If l <= back.second, they overlap.
            // If l == back.second + 1, they are adjacent.
            // To avoid overflow when back.second == INT64_MAX, we check:
