            if (l <= back.second || (l > back.second && l - 1 == back.second)) {
                if (r > back.second) {
                    back.second = r;
                }
            } else {
                merged.emplace_back(l, r);
            }
        }
    }

    std::cout << merged.size() << "\n";
    for (const auto& [l, r] : merged) {
        std::cout << l << " " << r << "\n";
    }

    return 0;
}
