struct SegTree {
    int n;
    vector<long long> sum;
    vector<long long> mul;
    vector<long long> add;

    SegTree(int n_) : n(n_), sum(4 * n), mul(4 * n, 1), add(4 * n, 0) {}

    void build(int node, int l, int r, const vector<long long>& a) {
        if (l == r) {
            sum[node] = a[l];
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, a);
        build(2 * node + 1, mid + 1, r, a);
        sum[node] = (sum[2 * node] + sum[2 * node + 1]) % MOD;
    }

    void push(int node, int l, int r) {
        if (mul[node] == 1 && add[node] == 0) return;
        int mid = (l + r) / 2;
        // Apply current tag to left child
        long long m1 = mul[node], a1 = add[node];
        mul[2 * node] = (mul[2 * node] * m1) % MOD;
        add[2 * node] = (add[2 * node] * m1 + a1) % MOD;
        sum[2 * node] = (sum[2 * node] * m1 + a1 * (mid - l + 1)) % MOD;

        // Apply current tag to right child
        mul[2 * node + 1] = (mul[2 * node + 1] * m1) % MOD;
        add[2 * node + 1] = (add[2 * node + 1] * m1 + a1) % MOD;
        sum[2 * node + 1] = (sum[2 * node + 1] * m1 + a1 * (r - mid)) % MOD;

        mul[node] = 1;
        add[node] = 0;
    }

